import { type EvidenceClass, type Gating, gatingFor, isEvidenceClass } from "./evidence";
import { type ArtifactSource, type CorpusPin, sha256Hex } from "./source";

export class CorpusVerificationError extends Error {
  constructor(
    public readonly path: string,
    detail: string,
  ) {
    super(`corpus verification failed for ${path}: ${detail}`);
    this.name = "CorpusVerificationError";
  }
}

export class InvalidEvidenceClassError extends Error {
  constructor(id: string, value: unknown) {
    super(`fixture ${id} has evidence class ${JSON.stringify(value ?? null)}, which is not one of the four`);
    this.name = "InvalidEvidenceClassError";
  }
}

export interface Fixture {
  id: string;
  group: string;
  evidenceClass: EvidenceClass;
  evidenceScope: string;
  gating: Gating;
  sourceDwg: { path: string; sha256: string; version: string; writer: string };
  expected: { path: string; sha256: string };
  signature: { path: string; sha256: string } | null;
  // Canonical .pvec is generated by pvec (P2.4) and does not exist yet; never invented here.
  canonicalPvec: { status: "PENDING"; waitsOn: string };
  entities: { id: string; type: string }[];
  capabilities: string[];
}

export interface Registry {
  revision: string;
  manifestSha256: string;
  numericPolicy: string;
  converterVersions: string[];
  fixtures: Fixture[];
  quarantined: { id: string; reason: string }[];
}

interface ManifestFixture {
  id: string;
  group: string;
  evidence_class?: unknown;
  evidence_scope: string;
  capabilities: string[];
  dwg: { path: string; sha256: string; dwg_version: string; writer: string };
  expected: { path: string; sha256: string };
}

const dec = new TextDecoder();

async function readVerified(src: ArtifactSource, path: string, sha256: string, what: string): Promise<Uint8Array> {
  let bytes: Uint8Array;
  try {
    bytes = await src.read(path);
  } catch (e) {
    throw new CorpusVerificationError(path, `${what} could not be read (${(e as Error).message})`);
  }
  const got = await sha256Hex(bytes);
  if (got !== sha256) throw new CorpusVerificationError(path, `${what} hash ${got} differs from the pinned ${sha256}`);
  return bytes;
}

export async function loadRegistry(src: ArtifactSource, pin: CorpusPin): Promise<Registry> {
  const base = pin.revision;
  const mBytes = await readVerified(src, `${base}/manifest.json`, pin.manifestSha256, "manifest");
  const manifest = JSON.parse(dec.decode(mBytes)) as {
    corpus_revision: string;
    numeric_policy_version: string;
    container_images: Record<string, string>;
    fixtures: ManifestFixture[];
  };
  if (manifest.corpus_revision !== pin.revision) {
    throw new CorpusVerificationError(
      `${base}/manifest.json`,
      `manifest declares revision ${manifest.corpus_revision}, the pin says ${pin.revision}`,
    );
  }

  const relDir = `release/${pin.release.name}`;
  const release = JSON.parse(
    dec.decode(await readVerified(src, `${relDir}/manifest.json`, pin.release.manifestSha256, "release manifest")),
  ) as { pins: { corpus: { manifest_sha256: string }; converters: Record<string, string>; signatures: Record<string, string> } };
  if (release.pins.corpus.manifest_sha256 !== pin.manifestSha256) {
    throw new CorpusVerificationError(`${relDir}/manifest.json`, "the release pins a different corpus manifest");
  }

  const q = JSON.parse(
    dec.decode(await readVerified(src, `${base}/quarantine.json`, pin.quarantineSha256, "quarantine list")),
  ) as { excluded: { id: string; reason: string }[]; quarantined: { id: string; reason: string }[] };
  const quarantined = [...q.excluded, ...q.quarantined].map(({ id, reason }) => ({ id, reason }));

  const fixtures: Fixture[] = [];
  for (const f of manifest.fixtures) {
    if (!isEvidenceClass(f.evidence_class)) throw new InvalidEvidenceClassError(f.id, f.evidence_class);
    const expectedBytes = await readVerified(src, `${base}/fixtures/${f.id}/expected.math.json`, f.expected.sha256, "expected.math.json");
    const expected = JSON.parse(dec.decode(expectedBytes)) as {
      fixture_id: string;
      evidence_class: string;
      entities: { id: string; class: string }[];
    };
    const ePath = `${base}/fixtures/${f.id}/expected.math.json`;
    if (expected.fixture_id !== f.id) throw new CorpusVerificationError(ePath, `record is for ${expected.fixture_id}`);
    if (expected.evidence_class !== f.evidence_class) {
      throw new CorpusVerificationError(ePath, `record says ${expected.evidence_class}, manifest says ${f.evidence_class}`);
    }
    const sigSha = release.pins.signatures[f.id];
    let signature: Fixture["signature"] = null;
    if (sigSha) {
      const path = `${relDir}/signatures/${f.id}.signature.json`;
      await readVerified(src, path, sigSha, "signature");
      signature = { path, sha256: sigSha };
    }
    fixtures.push({
      id: f.id,
      group: f.group,
      evidenceClass: f.evidence_class,
      evidenceScope: f.evidence_scope,
      gating: gatingFor(f.evidence_class),
      sourceDwg: { path: f.dwg.path, sha256: f.dwg.sha256, version: f.dwg.dwg_version, writer: f.dwg.writer },
      expected: { path: ePath, sha256: f.expected.sha256 },
      signature,
      canonicalPvec: { status: "PENDING", waitsOn: "libviprs/pvec#1 P2.4" },
      entities: expected.entities.map((e) => ({ id: e.id, type: e.class })),
      capabilities: f.capabilities,
    });
  }

  return {
    revision: manifest.corpus_revision,
    manifestSha256: pin.manifestSha256,
    numericPolicy: manifest.numeric_policy_version,
    converterVersions: [...Object.values(release.pins.converters), ...Object.values(manifest.container_images)],
    fixtures,
    quarantined,
  };
}

export function runSummary(reg: Registry): string {
  const count = (g: Gating) => reg.fixtures.filter((f) => f.gating === g).length;
  const lines = [
    `corpus revision: ${reg.revision} (manifest ${reg.manifestSha256})`,
    `numeric policy: ${reg.numericPolicy}`,
    ...reg.converterVersions.map((c) => `recorded converter or image: ${c}`),
    `gating: ${count("gate")}, report only: ${count("report")}`,
    `canonical pvec pending: ${reg.fixtures.filter((f) => f.canonicalPvec.status === "PENDING").length}`,
    ...reg.quarantined.map((q) => `QUARANTINED ${q.id} ${q.reason}`),
  ];
  return lines.join("\n");
}

export function exitStatus(reg: Registry, results: { fixtureId: string; passed: boolean }[]): 0 | 1 {
  let failed = false;
  for (const r of results) {
    const f = reg.fixtures.find((x) => x.id === r.fixtureId);
    if (!f) {
      if (reg.quarantined.some((q) => q.id === r.fixtureId)) continue;
      throw new Error(`result for unknown fixture ${r.fixtureId}`);
    }
    if (f.gating === "gate" && !r.passed) failed = true;
  }
  return failed ? 1 : 0;
}
